package metadatacache

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/vovanbl411/gentoo-update-intelligence/internal/metadatagenerator"
)

// Store keeps generated bytes and provenance under a compatibility key.
type Store struct{ directory string }

type entry struct {
	Inputs Inputs                   `json:"inputs"`
	Result metadatagenerator.Result `json:"result"`
}

func NewStore(directory string) (*Store, error) {
	if directory == "" {
		return nil, errors.New("metadata cache directory is required")
	}
	return &Store{directory: directory}, nil
}

// Load validates both the stored inputs and the generated bytes before reuse.
func (s *Store) Load(input Inputs) (metadatagenerator.Result, bool, error) {
	key, err := Key(input)
	if err != nil {
		return metadatagenerator.Result{}, false, err
	}
	data, err := os.ReadFile(filepath.Join(s.directory, key+".json"))
	if errors.Is(err, os.ErrNotExist) {
		return metadatagenerator.Result{}, false, nil
	}
	if err != nil {
		return metadatagenerator.Result{}, false, err
	}
	var saved entry
	if err := json.Unmarshal(data, &saved); err != nil {
		return metadatagenerator.Result{}, false, fmt.Errorf("invalid cached metadata: %w", err)
	}
	savedKey, err := Key(saved.Inputs)
	if err != nil || savedKey != key {
		return metadatagenerator.Result{}, false, errors.New("cached metadata inputs do not match key")
	}
	if err := validateResult(input, saved.Result); err != nil {
		return metadatagenerator.Result{}, false, err
	}
	return saved.Result, true, nil
}

// Save atomically publishes a complete result; incomplete writes are not reused.
func (s *Store) Save(input Inputs, result metadatagenerator.Result) error {
	key, err := Key(input)
	if err != nil {
		return err
	}
	if err := validateResult(input, result); err != nil {
		return err
	}
	data, err := json.Marshal(entry{Inputs: input, Result: result})
	if err != nil {
		return err
	}
	if err := os.MkdirAll(s.directory, 0o700); err != nil {
		return err
	}
	temporary, err := os.CreateTemp(s.directory, ".metadata-")
	if err != nil {
		return err
	}
	defer os.Remove(temporary.Name())
	if _, err := temporary.Write(data); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Sync(); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}
	return os.Rename(temporary.Name(), filepath.Join(s.directory, key+".json"))
}

func validateResult(input Inputs, result metadatagenerator.Result) error {
	provenance := result.Provenance
	digest := sha256.Sum256(result.Content)
	sha := hex.EncodeToString(digest[:])
	if result.SHA256 != sha || provenance.CacheSHA256 != sha ||
		provenance.ReferenceCommit != input.ReferenceCommit || provenance.SelectedCommit != input.SourceCommit ||
		provenance.EbuildBlobID != input.EbuildBlob || provenance.Profile != input.Profile || provenance.PortageVersion != input.PortageVersion ||
		provenance.EbuildPath != input.Category+"/"+input.Name+"/"+input.Name+"-"+input.Version+".ebuild" ||
		provenance.CachePath != "metadata/md5-cache/"+input.Category+"/"+input.Name+"-"+input.Version ||
		len(provenance.MasterRevisions) != len(input.Masters) {
		return errors.New("generated metadata provenance does not match cache inputs")
	}
	for i, master := range input.Masters {
		if provenance.MasterRevisions[i].Name != master.Name || provenance.MasterRevisions[i].Commit != master.Commit {
			return errors.New("generated metadata master revisions do not match cache inputs")
		}
	}
	return nil
}
